import 'dart:convert';
import 'dart:ui' show PlatformDispatcher;

import 'package:flutter/services.dart' show rootBundle;

/// UI strings in every supported language, loaded from
/// assets/i18n/strings.json (generated by tool/i18n_source.py; the native
/// macOS host reads the same file). Look strings up with [tr].
class I18n {
  I18n._();

  /// Setting value meaning "use the OS language".
  static const system = 'system';

  static List<String> languages = const ['zh'];
  static Map<String, String> names = const {};
  static Map<String, Map<String, String>> _strings = const {};
  static String _lang = 'zh';

  /// The resolved language code currently in use (zh, en, es, ...).
  static String get lang => _lang;

  static Future<void> load() async {
    try {
      final raw = await rootBundle.loadString('assets/i18n/strings.json');
      final doc = jsonDecode(raw) as Map<String, dynamic>;
      languages = (doc['languages'] as List).cast<String>();
      names = (doc['names'] as Map).cast<String, String>();
      _strings = (doc['strings'] as Map<String, dynamic>).map(
        (lang, table) => MapEntry(lang, (table as Map).cast<String, String>()),
      );
    } catch (_) {
      // Missing table: [tr] falls back to the key itself.
    }
    apply(system);
  }

  /// Maps a setting ("system" or a language code) to a supported language.
  static String resolve(String setting) {
    if (setting != system && languages.contains(setting)) return setting;
    for (final locale in PlatformDispatcher.instance.locales) {
      if (languages.contains(locale.languageCode)) return locale.languageCode;
    }
    return languages.contains('en') ? 'en' : languages.first;
  }

  static void apply(String setting) => _lang = resolve(setting);

  static String lookup(String key) =>
      _strings[_lang]?[key] ??
      _strings['en']?[key] ??
      _strings['zh']?[key] ??
      key;
}

/// Localized string for [key], with `{name}` placeholders filled from [args].
String tr(String key, [Map<String, Object?> args = const {}]) {
  var text = I18n.lookup(key);
  args.forEach(
    (name, value) => text = text.replaceAll('{$name}', '${value ?? '--'}'),
  );
  return text;
}
